mapper.select:
SELECT t1.id, t1.`code`, t1.`name`, t2.device_genre_id, t2.device_genre_name, t1.trigger_level_id as alarmLevelId, t1.trigger_level_name as alarmLevelName, t1.trigger_type_id as alarmTypeId, t1.trigger_type_name as alarmTypeName, t1.enabled FROM rule t1 INNER JOIN rule_device_alarm t2 on t1.id = t2.rule_id
and t1.name like concat('%',#{param.keyword},'%')
and t1.enalbed = #{param.enabled}
and t2.device_genre_id = #{param.deviceGenreId}
and t2.device_model_id = #{param.deviceModelId}
and t1.trigger_level_id = #{param.alarmLevelId}
and t1.trigger_type_id = #{param.alarmTypeId}
order by t1.create_time desc
